function greet(p: { name: string }): string {
  return 'Hello, ' + p.name;
}

const dog = { name: 'Rex', legs: 4, bark: () => 'woof' };
// dog has more than greet needs, but it has a name
console.log(greet(dog));
console.log(greet({ name: 'Ada' }));

